<script setup lang="ts">import {computed} from 'vue';import {useRouter} from 'vue-router';const props=defineProps<{projectId:string}>();const router=useRouter();const dataset=computed(()=>{const x=sessionStorage.getItem(`voicelens:dataset:${props.projectId}`);return x?JSON.parse(x):null});function analyze(){if(dataset.value)router.push(`/p/${props.projectId}/analysis?dataset=${dataset.value.id}`)}</script>
<template><div class="card" data-testid="dataset-list"><h2>数据批次</h2><p v-if="dataset">{{dataset.name}} · {{dataset.rows.toLocaleString()}} 行 · {{dataset.status}}</p><p v-else class="muted">暂无数据批次</p><button v-if="dataset" @click="analyze">选择并分析</button></div></template>
